import collections
import gzip
import json
import statistics
from pathlib import Path

work = Path(__file__).parent
variants = ("baseline", "rows16", "rows8", "read_write_stream")
summary = []
for view in (0, 48, 96, 144):
    samples = {}
    for variant in variants:
        samples[variant] = []
        for trial in (1, 2, 3):
            path = work / f"fixed_{trial}_{variant}.json"
            if path.exists():
                rows = json.loads(path.read_text())
                samples[variant] += [row["milliseconds"] for row in rows if row["view"] == view]
    medians = {variant: statistics.median(values) for variant, values in samples.items() if values}
    if "baseline" in medians:
        summary.append(dict(view=view, samples_ms=samples, median_ms=medians,
                            less_time_percent={variant: 100 * (1 - value / medians["baseline"])
                                               for variant, value in medians.items()}))
(work / "fixed_summary.json").write_text(json.dumps(summary, indent=2) + "\n")
print(json.dumps(summary, indent=2))

profiles = {}
for variant in variants:
    paths = list((work / f"{variant}_trace").rglob("*.trace.json.gz"))
    if not paths:
        continue
    events = json.loads(gzip.decompress(paths[0].read_bytes()))["traceEvents"]
    gpu_pids = {e["pid"] for e in events if e.get("ph") == "M" and e.get("name") == "process_name"
                and "/device:GPU:" in e.get("args", {}).get("name", "")}
    times, metadata = collections.defaultdict(list), {}
    for event in events:
        if event.get("ph") != "X" or event.get("pid") not in gpu_pids or "dur" not in event:
            continue
        name = event["name"].split("_tensorptr")[0]
        times[name].append(event["dur"])
        if "kernel_details" in event.get("args", {}):
            metadata[name] = event["args"]["kernel_details"]
    rows = [dict(name=name, calls=len(values), mean_us=statistics.mean(values),
                 per_step_us=sum(values) / 20, kernel_details=metadata.get(name))
            for name, values in times.items()]
    rows.sort(key=lambda row: -row["per_step_us"])
    profiles[variant] = rows
    print(variant, rows[:3])
(work / "profiles.json").write_text(json.dumps(profiles, indent=2) + "\n")
